// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.rule.engineimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.rule.BrainRuleimport com.roshan.persona.brain.rule.RuleActionimport com.roshan.persona.brain.rule.RuleConditionimport com.roshan.persona.brain.rule.RuleEvaluationimport com.roshan.persona.brain.rule.registry.RuleRegistryimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Layer 1: Rule Engine. * * Evaluates declarative rules against an [Intent] + [BrainContext]. Rules are * checked in priority order (lower = higher priority). First matching rule * wins. If no rule matches, defers to Layer 2 (SkillRouter). * * Evaluation is side-effect-free — actions are returned, not executed. * The Brain orchestrator executes the action. * * Performance budget: p50 < 5ms, p95 < 8ms, p99 < 12ms. * * @see <a href="docs/spec/module2-spec-review.pdf">§5 Layer 1</a> */@Singletonclass RuleEngine @Inject constructor(    private val ruleRegistry: RuleRegistry,) {    /**     * Evaluate all rules against [intent] + [context].     *     * @return [RuleEngineResult] — either a matching rule was found, or no match.     */    fun evaluate(intent: Intent, context: BrainContext): RuleEngineResult {        val startNanos = System.nanoTime()        val activeRules = ruleRegistry.getActiveRules()        var matchedRule: BrainRule? = null        for (rule in activeRules) {            if (!rule.isEnabled) {                continue  // skip disabled rules            }            val matched = try {                evaluateCondition(rule.condition, intent, context)            } catch (t: Throwable) {                Timber.tag("NOUS.L1").e(t, "Rule ${rule.id} evaluation threw")                false            }            if (matched) {                matchedRule = rule                break  // first match wins (priority-ordered)            }        }        val durationMs = (System.nanoTime() - startNanos) / 1_000_000        return if (matchedRule != null) {            Timber.tag("NOUS.L1").v(                "Rule matched: %s (priority=%d, %dms, %d rules checked)",                matchedRule.id,                matchedRule.priority,                durationMs,                activeRules.size,            )            RuleEngineResult.Matched(                rule = matchedRule,                action = matchedRule.action,                durationMs = durationMs,            )        } else {            Timber.tag("NOUS.L1").v("No rule matched (%dms, %d rules checked)", durationMs, activeRules.size)            RuleEngineResult.NoMatch(                durationMs = durationMs,                rulesChecked = activeRules.size,            )        }    }    /** Evaluate a single condition against intent + context. */    private fun evaluateCondition(        condition: RuleCondition,        intent: Intent,        context: BrainContext,    ): Boolean {        return when (condition) {            is RuleCondition.IntentIs -> intent::class == condition.intent            is RuleCondition.IntentMatches -> condition.predicate(intent)            is RuleCondition.And -> condition.conditions.all {                evaluateCondition(it, intent, context)            }            is RuleCondition.Or -> condition.conditions.any {                evaluateCondition(it, intent, context)            }            is RuleCondition.Not -> !evaluateCondition(condition.condition, intent, context)            is RuleCondition.Context -> condition.predicate(context)            RuleCondition.Always -> true        }    }}/** * Result of rule engine evaluation. */sealed interface RuleEngineResult {    /** A rule matched and should fire. */    data class Matched(        val rule: BrainRule,        val action: RuleAction,        val durationMs: Long,    ) : RuleEngineResult    /** No rule matched — defer to next layer (Layer 2). */    data class NoMatch(        val durationMs: Long,        val rulesChecked: Int,    ) : RuleEngineResult}